#include <bits/stdc++.h>//分讨
using namespace std;
#define int long long
signed main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n, m, x1;
	cin >> n >> m >> x1;
	if((n<=2&&m<=2)&&n*m<=x1){
		for(int i=1;i<=n;i++){
			if(i<n)
			for(int j=1;j<=m;j++){
				cout<<1<<' ';
			}
			else{
				for(int j=1;j<m;j++){
					cout<<1<<' ';
				}
				cout<<x1-n*m+1<<' ';
			}
			cout<<'\n';
		}
		return 0;
	}
	if (x1 * 2 % (n * m) != 0) {
		cout << -1 << '\n';
		return 0;
	}
	x1 *= 2;
	x1 /= n;
	x1 /= m;
	int a1, dd, boo = 0;
	if (x1 - (n - 1) >= 2 && (x1 - (n - 1)) % 2 == 0) {
		dd = 1;
		a1 = (x1 - (n - 1)) / 2;
		boo = 1;
	} else if (x1 - 2 * (n - 1) >= 2 && (x1 - 2 * (n - 1)) % 2 == 0) {
		dd = 2;
		a1 = (x1 - 2 * (n - 1)) / 2;
		boo = 1;
	} else if (x1 >= 2 && (x1) % 2 == 0) {
		dd = 0;
		a1 = x1 / 2;
		boo = 1;
	}
	if (boo == 1) {
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= m; j++)
				cout << a1 << ' ';
			cout << '\n';
			a1 += dd;
		}
	} else {
		cout << "-1" << '\n';
	}
}



